/* ============================================================
   Poll - Bootstrap 5 (PollNew)
   ============================================================ */

.poll-bs5
{
    font-size: 14px;
    color: var(--bs-body-color, #212529);
}

.poll-bs5 .poll-card
{
    border-radius: 0.5rem;
    overflow: hidden;
}

.poll-bs5 .poll-page-title
{
    color: inherit;
}

.poll-bs5 .poll-person-info
{
    font-size: 1rem;
    font-weight: 600;
    color: var(--bs-info-text-emphasis, #055160);
    background-color: var(--bs-info-bg-subtle, #cff4fc);
    border-color: var(--bs-info-border-subtle, #9eeaf9);
}

.poll-bs5 .poll-part-title
{
    font-size: 1.1rem;
}

.poll-bs5 .poll-part-brief
{
    font-size: 0.95rem;
    color: var(--bs-secondary-color, #6c757d);
}

.poll-bs5 .poll-question
{
    font-size: 1rem;
    color: var(--bs-body-color, #212529);
    line-height: 1.5;
}

.poll-bs5 .poll-question-item
{
    transition: box-shadow 0.2s ease, border-color 0.2s ease;
}

.poll-bs5 .poll-question-highlight
{
    border-color: var(--bs-warning, #ffc107) !important;
    box-shadow: 0 0 0 0.25rem rgba(255, 193, 7, 0.35) !important;
    background-color: var(--bs-warning-bg-subtle, #fff3cd) !important;
}

.poll-bs5 .poll-question-highlight .poll-question
{
    color: var(--bs-danger, #dc3545);
}

.poll-bs5 .form-check
{
    min-height: 1.5rem;
    padding-left: 0;
}

.poll-bs5 .form-check-input
{
    margin-left: 0;
    margin-right: 0.35rem;
    float: none;
}

.poll-bs5 .form-check label
{
    font-weight: normal;
    cursor: pointer;
}

.poll-bs5 .pol-option-col .form-check
{
    padding: 0.35rem 0.5rem;
    border-radius: 0.375rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    background-color: var(--bs-body-bg, #fff);
    transition: background-color 0.15s ease, border-color 0.15s ease;
}

.poll-bs5 .pol-option-col .form-check:hover
{
    background-color: var(--bs-light, #f8f9fa);
    border-color: var(--bs-primary, #0d6efd);
}

.poll-bs5 .pol-fill-label
{
    font-weight: 500;
    color: var(--bs-secondary-color, #6c757d);
}

.poll-bs5 .Question_Table
{
    margin-bottom: 1rem;
}

.poll-bs5 .poll-new-table thead th
{
    font-size: 0.875rem;
    vertical-align: middle;
}

.poll-bs5 .poll-new-table tbody td
{
    font-size: 0.875rem;
    vertical-align: middle;
}

.poll-bs5 .pol-ratio-cell
{
    white-space: nowrap;
    width: 56px;
    padding: 0.35rem !important;
}

.poll-bs5 .pol-ratio-cell .form-check
{
    padding-left: 0;
    margin-bottom: 0;
}

.poll-bs5 .poll-page-thanks p
{
    margin-bottom: 0;
}

.poll-bs5 .poll-page-command .btn-primary
{
    min-width: 200px;
}

@media (max-width: 767.98px)
{
    .poll-bs5 .card-body
    {
        padding: 1rem !important;
    }

    .poll-bs5 .poll-page-command .btn-primary
    {
        width: 100%;
        min-width: 0;
    }

    .poll-bs5 .pol-ratio-cell
    {
        white-space: normal;
        width: auto;
    }
}

